  "verdict": "request_changes",
  "summary": "Candidate fails to cache per tenant, causing incorrect behavior when different tenants use the same record_id.",
  "findings": [
    {
      "finding_id": "cache-key-mismatch",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 4,
      "severity": "high",
      "description": "Cache key does not include tenant, violating the requirement to cache separately for each (tenant, record_id).",
      "evidence": "If lookup is called with tenant='a', record_id='1', and then with tenant='b', record_id='1', the second call incorrectly returns the cached value for tenant 'a' instead of reloading for tenant 'b'."
